        solution: 0,
        explanationEn: 'In spoken English, making the person (Indirect Object) the subject of the passive is far more natural (\'Rahul was given an award\').',
        explanationMl: 'സംസാരത്തിൽ വ്യക്തിയെ സബ്ജക്റ്റാക്കി \'Rahul was given an award\' എന്ന് പറയുന്നതാണ് കൂടുതൽ സ്വാഭാവികം.',
        audioVoiceText: 'Rahul was given an award.',
