  RealmGameSpec(
    day: 53,
    gameIndex: 1,
    title: 'Causative Workshop',
    subtitle: 'Master delegating actions using HAVE, GET, MAKE, LET, and HELP',
    archetype: GameArchetype.sortingFactory,
    regionId: 'grammar_citadel',
    regionName: 'Complex Grammar Citadel',
    englishTopic: 'Causative Structures – Have, Get, Make, Let, Help',
    descriptionEn: 'Distinguish between forcing (MAKE), persuading (GET), delegating (HAVE), permitting (LET), and assisting (HELP).',
    descriptionMl: 'മറ്റൊരാളെക്കൊണ്ട് ഒരു കാര്യം ചെയ്യിക്കുന്ന Causative (Make, Get, Have, Let, Help) ഘടനകൾ പഠിക്കുക.',
    icon: '🔧',
    accentColor: Color(0xFF3B82F6),
    xpReward: 50,
    coinReward: 25,
    rounds: [
      RealmChallengeRound(
        id: 1,
        promptEn: 'Service Delegation (HAVE something done): \'My car engine was making noises, so I ______ yesterday.\'',
        promptMl: 'മെക്കാനിക്കിനെക്കൊണ്ട് കാർ റിപ്പയർ ചെയ്യിപ്പിച്ചു എന്ന് പറയാൻ:',
        options: ['had my car repaired (Have + Object + V3)', 'repaired my car', 'got to repair my car', 'made my car repair'],
        solution: 0,
        explanationEn: '\'Have + Object + V3\' means you hired or arranged for someone else to perform a service for you.',
        explanationMl: 'മറ്റൊരാളെക്കൊണ്ട് സർവീസ് ചെയ്യിപ്പിച്ചു എന്ന് പറയാൻ \'had my car repaired\' എന്ന് ഉപയോഗിക്കുന്നു.',
        audioVoiceText: 'I had my car repaired yesterday.',
      ),
      RealmChallengeRound(
        id: 2,
        promptEn: 'Causative \'MAKE\' (Forcing / Compelling): \'The army sergeant made the recruits ______ fifty push-ups.\'',
        promptMl: 'നിർബന്ധിച്ച് ചെയ്യിപ്പിക്കുന്ന \'make\' ന് ശേഷം \'to\' വേണമോ?',
        options: ['do (Bare infinitive without \'to\')', 'to do', 'doing', 'done'],
        solution: 0,
        explanationEn: 'Causative \'make\' takes Person + BARE INFINITIVE without \'to\' (\'made them do\').',
        explanationMl: 'Causative \'make\' ന് ശേഷം bare infinitive വരുന്നു: made them do (to do തെറ്റാണ്).',
        audioVoiceText: 'Made the recruits do fifty push-ups.',
      ),
      RealmChallengeRound(
        id: 3,
        promptEn: 'Causative \'GET\' (Persuading / Convincing): \'She got her brother ______ her laptop.\'',
        promptMl: '\'Get\' എന്ന ക്രിയക്ക് ശേഷം \'to\' വേണമോ?',
        options: ['to fix (Get takes Person + TO-infinitive!)', 'fix', 'fixing', 'fixed'],
        solution: 0,
        explanationEn: 'CRUCIAL DIFFERENCE: While \'have\' takes a bare infinitive, \'GET\' takes a TO-INFINITIVE (\'got him to fix\', but \'had him fix\')!',
        explanationMl: 'വളരെ പ്രധാനം: \'Have\' ന് ശേഷം \'to\' വരില്ല, എന്നാൽ \'Get\' ന് ശേഷം \'to\' നിർബന്ധമാണ്: got him to fix.',
        audioVoiceText: 'She got her brother to fix her laptop.',
      ),
      RealmChallengeRound(
        id: 4,
        promptEn: 'Causative \'LET\' (Permitting / Allowing): \'Her parents let her ______ on the weekend excursion.\'',
        promptMl: 'അനുവാദം നൽകുന്ന \'let\' ന് ശേഷം ഏത് രൂപം വരണം?',
        options: ['go (Bare infinitive)', 'to go', 'going', 'gone'],
        solution: 0,
        explanationEn: 'Causative \'let\' takes Person + BARE INFINITIVE (\'let her go\').',
        explanationMl: '\'Let\' ന് ശേഷം bare infinitive വരുന്നു: let her go.',
        audioVoiceText: 'Her parents let her go.',
      ),
      RealmChallengeRound(
        id: 5,
        promptEn: 'Causative \'HELP\' (Assisting): \'He helped me ______ the heavy luggage.\'',
        promptMl: 'സഹായിക്കുക എന്നതിന് ഏത് രൂപം വരണം?',
        options: ['carry OR to carry (Both bare and to-infinitive are correct!)', 'carrying only', 'carried', 'for carry'],
        solution: 0,
        explanationEn: '\'Help\' is unique in English: it can be followed by either a bare infinitive (\'helped me carry\') or a to-infinitive (\'helped me to carry\').',
        explanationMl: '\'Help\' ന് ശേഷം bare infinitive (carry) അല്ലെങ്കിൽ to-infinitive (to carry) ഉപയോഗിക്കാം; രണ്ടും ശരിയാണ്.',
        audioVoiceText: 'He helped me carry the luggage.',
      ),
    ],
  ),

