  RealmGameSpec(
    day: 54,
    gameIndex: 1,
    title: 'Speech Bridge',
    subtitle: 'Convert direct quote statements into reported indirect speech',
    archetype: GameArchetype.sentenceBuilder,
    regionId: 'grammar_citadel',
    regionName: 'Complex Grammar Citadel',
    englishTopic: 'Direct and Indirect Speech – Statements',
    descriptionEn: 'Report statements shifting pronouns, tenses, and time/place words across the speech bridge.',
    descriptionMl: 'നേരിട്ടുള്ള സംഭാഷണങ്ങളെ (Direct) പരോക്ഷ രൂപത്തിലേക്ക് (Indirect) മാറ്റുന്ന നിയമങ്ങൾ പ്രയോഗിക്കുക.',
    icon: '🌉',
    accentColor: Color(0xFF10B981),
    xpReward: 50,
    coinReward: 25,
    rounds: [
      RealmChallengeRound(
        id: 1,
        promptEn: 'Direct: Rahul said, \'I am feeling unwell today.\' -> Indirect:',
        promptMl: 'ശരിയായ ഇൻഡയറക്റ്റ് രൂപം ഏതാണ്?',
        options: ['Rahul said that he was feeling unwell that day.', 'Rahul said that I am feeling unwell today.', 'Rahul said that he is feeling unwell that day.', 'Rahul said that he has been feeling unwell today.'],
        solution: 0,
        explanationEn: 'Rule: \'am feeling\' backshifts to \'was feeling\'; \'I\' shifts to \'he\'; \'today\' shifts to \'that day\'.',
        explanationMl: '\'Am\' എന്നത് \'was\' ആകും, \'I\' എന്നത് \'he\' ആകും, \'today\' എന്നത് \'that day\' ആയി മാറും.',
        audioVoiceText: 'Rahul said that he was feeling unwell that day.',
      ),
      RealmChallengeRound(
        id: 2,
        promptEn: 'Direct: She said, \'I bought a new car yesterday.\' -> Indirect:',
        promptMl: 'Past simple (bought) ഇൻഡയറക്റ്റിൽ എന്തിലേക്ക് മാറുന്നു?',
        options: ['She said that she had bought a new car the previous day.', 'She said that she bought a new car yesterday.', 'She said that she has bought a new car the previous day.', 'She said that she had been bought a new car.'],
        solution: 0,
        explanationEn: 'Rule: Past Simple (\'bought\') backshifts to Past Perfect (\'had bought\'); \'yesterday\' shifts to \'the previous day\'.',
        explanationMl: 'Past Simple എന്നത് Past Perfect (had bought) ആകും, yesterday എന്നത് the previous day ആകും.',
        audioVoiceText: 'She said she had bought a car the previous day.',
      ),
      RealmChallengeRound(
        id: 3,
        promptEn: 'Direct: They said, \'We will help you tomorrow.\' -> Indirect:',
        promptMl: '\'Will\' എന്തിലേക്ക് മാറുന്നു?',
        options: ['They said that they would help me the following day.', 'They said that they will help me tomorrow.', 'They said that they would help you tomorrow.', 'They said that they can help me.'],
        solution: 0,
        explanationEn: 'Rule: \'will\' shifts to \'would\'; \'tomorrow\' shifts to \'the following day\' or \'the next day\'.',
        explanationMl: '\'Will\' എന്നത് \'would\' ആകും, \'tomorrow\' എന്നത് \'the following day\' ആയി മാറും.',
        audioVoiceText: 'They said they would help me the following day.',
      ),
      RealmChallengeRound(
        id: 4,
        promptEn: 'Reporting verb: \'SAY\' vs \'TELL\': \'She ______ that the report was ready.\' vs \'She ______ me that...\'',
        promptMl: 'Say, Tell എന്നിവയുടെ കൃത്യമായ ഉപയോഗം:',
        options: ['said; told (Tell requires a personal listener object; say does not)', 'told; said', 'said; said', 'told; told'],
        solution: 0,
        explanationEn: '\'Tell\' requires an indirect personal object (\'told me\'); \'say\' does not take a personal object directly (\'said that...\').',
        explanationMl: '\'Tell\' ന് ശേഷം ആർക്ക് പറഞ്ഞു എന്ന് വേണം (told me). \'Say\' ന് ശേഷം listener ആവശ്യമില്ല (said that).',
        audioVoiceText: 'She said that, and she told me that.',
      ),
      RealmChallengeRound(
        id: 5,
        promptEn: 'Time shifter: In reported speech, \'NOW\' typically becomes:',
        promptMl: 'ഇൻഡയറക്റ്റ് സ്പീച്ചിൽ \'NOW\' എന്തായി മാറുന്നു?',
        options: ['then', 'at the moment', 'today', 'yesterday'],
        solution: 0,
        explanationEn: '\'Now\' shifts chronologically to \'then\' or \'at that time\'.',
        explanationMl: '\'Now\' എന്നത് \'then\' (ആ സമയത്ത്) ആയി മാറുന്നു.',
        audioVoiceText: 'Now becomes then.',
      ),
    ],
  ),

