        options: ['She asked me where I lived. (Statement word order, no question mark)', 'She asked me where did I live?', 'She asked me where do I live.', 'She asked where lived I.'],
        solution: 0,
        explanationEn: 'CRUCIAL RULE: In reported questions, question inversion and auxiliary \'do/did\' disappear! Word order is Subject + Verb: \'where I lived\'.',
        explanationMl: 'വളരെ പ്രധാനം: റിപ്പോർട്ട് ചെയ്യുമ്പോൾ ചോദ്യം സാധാരണ വാക്യമായി മാറും: \'where I lived\' (did I live എന്ന് ചോദിക്കരുത്).',
        audioVoiceText: 'She asked me where I lived.',
      ),
      RealmChallengeRound(
