        options: ['The officer asked if I was carrying any liquids.', 'The officer asked was I carrying liquids.', 'The officer asked whether was I carrying liquids.', 'The officer asked if I am carrying liquids.'],
        solution: 0,
        explanationEn: 'Yes/No questions use \'if / whether\' + Subject + Verb (\'if I was carrying\').',
        explanationMl: 'Yes/No ചോദ്യങ്ങളിൽ if / whether ചേർത്ത് \'if I was carrying\' എന്ന് സബ്ജക്റ്റും വെർബും ക്രമീകരിക്കുക.',
        audioVoiceText: 'The officer asked if I was carrying any liquids.',
      ),
      RealmChallengeRound(
        id: 3,
        promptEn: 'Direct WH-Question in Past: He asked, \'Why did you resign from the company?\' -> Reported:',
        promptMl: '\'Did you resign\' ഇൻഡയറക്റ്റിൽ എന്തിലേക്ക് മാറുന്നു?',
        options: ['He asked why I had resigned from the company.', 'He asked why did I resign.', 'He asked why I resigned.', 'He asked why had I resigned.'],
        solution: 0,
        explanationEn: '\'Did you resign\' (Past Simple) backshifts to Past Perfect in statement order (\'why I had resigned\').',
        explanationMl: '\'Did you resign\' എന്നത് Past Perfect ആയി \'why I had resigned\' എന്ന് മാറുന്നു.',
        audioVoiceText: 'He asked why I had resigned.',
      ),
      RealmChallengeRound(
