        promptEn: 'Direct Question with modal: He asked, \'Can you assist me tomorrow?\' -> Reported:',
        promptMl: 'Can ഉള്ള ചോദ്യം റിപ്പോർട്ട് ചെയ്യുമ്പോൾ:',
        options: ['He asked if I could assist him the following day.', 'He asked if could I assist him.', 'He asked whether can I assist him.', 'He asked could I assist him.'],
        solution: 0,
        explanationEn: '\'Can\' shifts to \'could\' with statement order: \'if I could assist him the following day\'.',
        explanationMl: 'If I could assist him the following day - കൃത്യമായ ഇൻഡയറക്റ്റ് രൂപം.',
