        options: ['No, they are declarative statements and must end with a period / full stop.', 'Yes, always.', 'Only if they start with why.', 'Only in emails.'],
        solution: 0,
        explanationEn: 'Reported questions are grammatical statements asserting that an inquiry was made; they end with a period (.), NOT a question mark (?).',
        explanationMl: 'ഇൻഡയറക്റ്റ് ചോദ്യങ്ങൾ വ്യാകരണപരമായി സാധാരണ പ്രസ്താവനകളാണ്, അതിനാൽ അവസാനം ഫുൾസ്റ്റോപ്പ് (.) ആണ് വരേണ്ടത്.',
