  RealmGameSpec(
    day: 56,
    gameIndex: 1,
    title: 'Backshift Tunnel',
    subtitle: 'Navigate the complete chronological tense backshifting matrix',
    archetype: GameArchetype.timelineSequencer,
    regionId: 'grammar_citadel',
    regionName: 'Complex Grammar Citadel',
    englishTopic: 'Reported Speech – Backshifting and Exceptions',
    descriptionEn: 'Traverse the backshift matrix: Present Simple -> Past Simple -> Past Perfect.',
    descriptionMl: 'ടെൻസുകൾ ഒരു പടി പുറകോട്ട് മാറുന്ന (Backshifting) സമഗ്ര മാട്രിക്സ് പഠിക്കുക.',
    icon: '⏳',
    accentColor: Color(0xFF6366F1),
    xpReward: 50,
    coinReward: 25,
    rounds: [
      RealmChallengeRound(
        id: 1,
        promptEn: 'Backshift Step 1: What does PRESENT CONTINUOUS (is doing) backshift to?',
        promptMl: 'Present Continuous ഇൻഡയറക്റ്റിൽ എന്തിലേക്ക് മാറുന്നു?',
        options: ['Past Continuous (was doing)', 'Past Perfect Continuous (had been doing)', 'Present Perfect (has done)', 'Simple Past (did)'],
        solution: 0,
        explanationEn: 'Present Continuous (\'is writing\') backshifts one step into Past Continuous (\'was writing\').',
        explanationMl: 'Present Continuous എന്നത് Past Continuous (was doing) ആയി മാറുന്നു.',
        audioVoiceText: 'Present Continuous shifts to Past Continuous.',
      ),
      RealmChallengeRound(
        id: 2,
        promptEn: 'Backshift Step 2: What does PAST CONTINUOUS (was doing) backshift to?',
        promptMl: 'Past Continuous ഇൻഡയറക്റ്റിൽ എന്തിലേക്ക് മാറുന്നു?',
        options: ['Past Perfect Continuous (had been doing)', 'Past Continuous (remains unchanged)', 'Present Continuous', 'Past Simple'],
        solution: 0,
        explanationEn: 'Past Continuous (\'was writing\') backshifts into Past Perfect Continuous (\'had been writing\').',
        explanationMl: 'Past Continuous എന്നത് Past Perfect Continuous (had been doing) ആയി മാറുന്നു.',
        audioVoiceText: 'Past Continuous shifts to Past Perfect Continuous.',
      ),
      RealmChallengeRound(
        id: 3,
        promptEn: 'Backshift Step 3: What does PAST PERFECT (had done) backshift to?',
        promptMl: 'Past Perfect (had done) ഇൻഡയറക്റ്റിൽ എന്തിലേക്ക് മാറുന്നു?',
        options: ['It CANNOT backshift any further (remains Past Perfect: had done)', 'Past Simple', 'Present Perfect', 'Future Past'],
        solution: 0,
        explanationEn: 'Past Perfect is the deepest past tense in English; it has nowhere further back to go, so it remains unchanged.',
        explanationMl: 'Past Perfect ന് പുറകിലേക്ക് മറ്റൊരു ടെൻസ് ഇല്ലാത്തതിനാൽ അത് \'had done\' എന്ന് മാറ്റമില്ലാതെ തുടരുന്നു.',
        audioVoiceText: 'Past Perfect cannot backshift further; it remains unchanged.',
      ),
      RealmChallengeRound(
        id: 4,
        promptEn: 'Backshift Step 4: Modals that DO NOT backshift: Which modal remains unchanged?',
        promptMl: 'ഇൻഡയറക്റ്റിൽ മാറ്റമില്ലാതെ തുടരുന്ന മോഡൽ ഏതാണ്?',
        options: ['Should, would, could, might, ought to (remain unchanged)', 'Will', 'Can', 'May'],
        solution: 0,
        explanationEn: 'Secondary modals (should, would, could, might, ought to) already represent the past/subjunctive and do not backshift.',
        explanationMl: 'Should, would, could, might എന്നിവ ഇൻഡയറക്റ്റിൽ മാറ്റമില്ലാതെ തുടരുന്നു.',
        audioVoiceText: 'Could, would, and should remain unchanged.',
      ),
      RealmChallengeRound(
        id: 5,
        promptEn: 'Backshift Step 5: What does \'MUST\' (obligation) shift to in the past?',
        promptMl: 'നിർബന്ധത്തെ സൂചിപ്പിക്കുന്ന \'must\' ഭൂതകാലത്തിൽ എന്തിലേക്ക് മാറുന്നു?',
        options: ['had to', 'musted', 'would must', 'should'],
        solution: 0,
        explanationEn: 'When \'must\' denotes past obligation, it backshifts to \'had to\'.',
        explanationMl: 'ഭൂതകാല ബാധ്യതയെ സൂചിപ്പിക്കുമ്പോൾ \'must\' എന്നത് \'had to\' ആയി മാറുന്നു.',
        audioVoiceText: 'Must backshifts to had to.',
      ),
    ],
  ),

