        options: ['She says that she loves classical music. (NO backshift when reporting verb is in present!)', 'She says that she loved classical music.', 'She says that she had loved music.', 'She says that she was love music.'],
        solution: 0,
        explanationEn: 'GOLDEN RULE: If the reporting verb is in the Present or Future (\'says\', \'will say\'), DO NOT backshift the tense!',
        explanationMl: 'വളരെ പ്രധാനം: റിപ്പോർട്ടിംഗ് വെർബ് പ്രസന്റിൽ (says) ആണെങ്കിൽ ടെൻസിൽ യാതൊരു മാറ്റവും വരുത്തരുത്: she loves.',
        audioVoiceText: 'No backshift when the reporting verb is present.',
      ),
      RealmChallengeRound(
