        promptEn: 'Exception 2: Universal Scientific Truth: \'The teacher said, \'Water freezes at zero degrees Celsius.\'\' -> Indirect:',
        promptMl: 'ശാസ്ത്രീയ സത്യങ്ങൾ റിപ്പോർട്ട് ചെയ്യുമ്പോൾ:',
        options: ['The teacher said that water freezes at zero degrees Celsius. (Remains Present Simple)', 'The teacher said that water froze at zero degrees.', 'The teacher said water had frozen.', 'The teacher said water was freezing.'],
