    descriptionMl: 'കോമ ആവശ്യമുള്ള നോൺ-ഡിഫൈനിംഗ് ക്ലോസുകളും ആവശ്യമില്ലാത്ത ഡിഫൈനിംഗ് ക്ലോസുകളും വേർതിരിക്കുക.',
