        options: [', who is a retired botanist,', 'who is a retired botanist', ', that is a retired botanist,', 'which is a botanist'],
        solution: 0,
        explanationEn: 'Non-defining relative clauses give non-essential extra details and MUST be enclosed in commas: \', who is a retired botanist,\'.',
        explanationMl: 'അധിക വിവരങ്ങൾ നൽകുന്ന നോൺ-ഡിഫൈനിംഗ് ക്ലോസുകൾക്ക് ഇരുവശത്തും കോമ (,) നിർബന്ധമാണ്.',
        audioVoiceText: 'My mother, who is a botanist, loves gardening.',
