        promptEn: 'Forbidden use of \'THAT\': Can you use \'THAT\' inside a non-defining clause with commas?',
        promptMl: 'കോമ ഉള്ള നോൺ-ഡിഫൈനിംഗ് ക്ലോസുകളിൽ \'THAT\' ഉപയോഗിക്കാൻ പാടുണ്ടോ?',
        options: ['NEVER! \'That\' can only be used in defining clauses without commas.', 'Yes, always.', 'Only with people.', 'Only in American English.'],
        solution: 0,
        explanationEn: 'CRUCIAL GRAMMAR RULE: \'That\' is STRICTLY FORBIDDEN in non-defining relative clauses with commas! Use \'which\' for things and \'who\' for people.',
